import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;

public class AccountLookupServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AccountLookupServlet.class.getName());

    // Connection pool managed by container
    private DataSource getDataSource() throws Exception {
        javax.naming.Context ctx = new javax.naming.InitialContext();
        return (DataSource) ctx.lookup("java:comp/env/jdbc/AccountDB");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String accountId = req.getParameter("id");
        String fields = req.getParameter("fields");

        // Basic null check
        if (accountId == null || accountId.isEmpty()) {
            resp.sendError(400, "Missing account id");
            return;
        }

        // Validate accountId is numeric
        if (!accountId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid account id format");
            return;
        }

        // Fields parameter allows selecting which columns to return
        // Default to safe set if not specified
        String columnList = "account_id, display_name, created_at";
        if (fields != null && !fields.isEmpty()) {
            // Attempt to restrict to known columns - but implementation is flawed
            columnList = sanitizeFieldList(fields);
        }

        String query = "SELECT " + columnList + " FROM accounts WHERE account_id = " + accountId;

        log.info("Executing lookup for account: " + accountId);

        try (Connection conn = getDataSource().getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            java.io.PrintWriter out = resp.getWriter();
            out.print("{");

            ResultSetMetaData meta = rs.getMetaData();
            if (rs.next()) {
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    if (i > 1) out.print(",");
                    out.print("\"" + meta.getColumnLabel(i) + "\":");
                    Object val = rs.getObject(i);
                    if (val instanceof Number) {
                        out.print(val);
                    } else {
                        out.print("\"" + escapeJson(String.valueOf(val)) + "\"");
                    }
                }
            } else {
                resp.sendError(404, "Account not found");
                return;
            }
            out.print("}");

        } catch (SQLException e) {
            log.warning("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } catch (Exception e) {
            log.warning("Lookup error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    /**
     * Attempts to sanitize field list by checking against allowed columns.
     * NOTE: This validation is bypassable - it splits on comma but doesn't
     * account for SQL expressions containing commas in subqueries.
     */
    private String sanitizeFieldList(String fields) {
        String[] allowed = {"account_id", "display_name", "email", "created_at", "status"};
        String[] requested = fields.split(",");
        StringBuilder sb = new StringBuilder();

        for (String f : requested) {
            String trimmed = f.trim().toLowerCase();
            // Flawed: only checks if the field STARTS WITH an allowed column name
            for (String a : allowed) {
                if (trimmed.startsWith(a)) {
                    if (sb.length() > 0) sb.append(", ");
                    sb.append(f.trim());
                    break;
                }
            }
        }

        return sb.length() > 0 ? sb.toString() : "account_id, display_name, created_at";
    }

    private String escapeJson(String s) {
        if (s == null) return "null";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r");
    }
}
